package app.materialclock.alarm import android.app.NotificationChannel import android.app.NotificationManager import android.app.Service import android.content.Intent import android.os.Build import android.os.IBinder import androidx.core.app.NotificationCompat class TimerService : Service() { override fun onBind(intent: Intent?): IBinder? = null override fun onCreate() { super.onCreate() createNotificationChannel() } fun startLiveNotification(timeLeftText: String, isFocusMode: Boolean) { val title = if (isFocusMode) "Focus Mode Active 🎯" else "Timer Running ⏱️" val notification = NotificationCompat.Builder(this, CHANNEL_ID) .setContentTitle(title) .setContentText(timeLeftText) .setSmallIcon(android.R.drawable.ic_lock_idle_alarm) .setOngoing(true) .setCategory(NotificationCompat.CATEGORY_STOPWATCH) .setPriority(NotificationCompat.PRIORITY_LOW) .build() startForeground(NOTIFICATION_ID, notification) } private fun createNotificationChannel() { if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) { val channel = NotificationChannel( CHANNEL_ID, "Live Timer Notifications", NotificationManager.IMPORTANCE_LOW ) val manager = getSystemService(NotificationManager::class.java) manager?.createNotificationChannel(channel) } } companion object { private const val CHANNEL_ID = "live_timer_channel" private const val NOTIFICATION_ID = 201 } } 